command:
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { checkout } from './src/app.js';
import { makeReceiptKey as billingKey } from './src/billing/receipt.js';
import { makeReceiptKey as reportKey } from './src/reports/receipt.js';
import { makeReceiptKey as responseKey } from './src/transport/receipt.js';

const invoice = { accountId: 'acme', sequence: 7 };
const calls = [];
const provider = { post: (...args) => { calls.push(args); return 'sent'; } };
assert.equal(await checkout(invoice, provider), 'sent');
assert.deepEqual(calls, [['/invoices', invoice, { 'Idempotency-Key': 'invoice/acme/0007' }]]);
assert.equal(billingKey(invoice), 'invoice/acme/0007');
assert.equal(reportKey({ id: 'example' }), 'report:example');
assert.equal(responseKey({ headers: { 'x-receipt': 'response-value' } }), 'response-value');
console.log('PASS: checkout sends the constructed billing key; similarly named helpers have different roles.');
